CREATE TABLE IF NOT EXISTS beaches (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  province_id TEXT REFERENCES provinces(id) ON DELETE SET NULL,
  municipality_id TEXT REFERENCES municipalities(id) ON DELETE SET NULL,
  destination_id TEXT REFERENCES destinations(id) ON DELETE SET NULL,
  beach_type TEXT NOT NULL DEFAULT 'arena-blanca',
  short_description TEXT,
  description TEXT,
  image_url TEXT,
  image_alt TEXT,
  gallery TEXT NOT NULL DEFAULT '[]',
  activities TEXT NOT NULL DEFAULT '[]',
  amenities TEXT NOT NULL DEFAULT '[]',
  water_color TEXT,
  sand_type TEXT,
  wave_intensity TEXT NOT NULL DEFAULT 'calma',
  crowd_level TEXT NOT NULL DEFAULT 'media',
  access_type TEXT NOT NULL DEFAULT 'publico',
  parking_available INTEGER NOT NULL DEFAULT 0,
  lifeguard_on_duty INTEGER NOT NULL DEFAULT 0,
  how_to_get_there TEXT,
  best_time_to_visit TEXT,
  latitude REAL,
  longitude REAL,
  rating REAL NOT NULL DEFAULT 4.5,
  is_popular INTEGER NOT NULL DEFAULT 0,
  is_featured INTEGER NOT NULL DEFAULT 0,
  seo_title TEXT,
  seo_description TEXT,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
  created_by TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_beaches_status ON beaches (status, name);
CREATE INDEX IF NOT EXISTS idx_beaches_location ON beaches (province_id, municipality_id, destination_id);

INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('playa-bavaro', 'playa-bavaro', 'Playa Bávaro', (SELECT id FROM provinces WHERE slug = 'la-altagracia'), 'salvaleon-de-higuey', 'bavaro', 'arena-blanca', 'La playa más famosa del Caribe, reconocida por la UNESCO como una de las mejores del mundo.', 'Playa Bávaro es el ícono de Punta Cana y del Caribe dominicano. Con más de 30 kilómetros de arena blanca como el azúcar y aguas cristalinas de color turquesa, ha sido reconocida por la UNESCO como una de las mejores playas del mundo. Bordeada de cocoteros y resorts de clase mundial, ofrece todas las comodidades mientras mantiene su belleza natural impresionante.', 'https://images.unsplash.com/photo-1781901227396-34e5fc040091?w=1200&h=800&fit=crop&q=80', 'Playa Bávaro', '[{"url":"https://images.unsplash.com/photo-1781901227396-34e5fc040091?w=1200&h=800&fit=crop&q=80","alt":"Playa Bávaro"},{"url":"https://images.unsplash.com/photo-1781901227396-34e5fc040091?w=1200&h=800&fit=crop&q=80","alt":"Playa Bávaro"},{"url":"https://images.unsplash.com/photo-1781901227396-34e5fc040091?w=1200&h=800&fit=crop&q=80","alt":"Playa Bávaro"},{"url":"https://images.unsplash.com/photo-1781901227396-34e5fc040091?w=1200&h=800&fit=crop&q=80","alt":"Playa Bávaro"}]', '["Snorkel","Parasailing","Catamarán","Paddleboard","Jet ski","Banana boat","Buceo"]', '["Sillas y sombrillas","Restaurantes","Bares de playa","Duchas","Baños","Deportes acuáticos"]', 'Turquesa cristalino', 'Arena blanca fina', 'calma', 'alta', 'semi-privado', 1, 1, '15 minutos desde el Aeropuerto Internacional de Punta Cana. Acceso principal por los resorts de la zona.', 'Todo el año, especialmente de diciembre a abril', 18.687, -68.4514, 4.9, 1, 1, 'Playa Bávaro | Playas de República Dominicana', 'La playa más famosa del Caribe, reconocida por la UNESCO como una de las mejores del mundo.', 'published');
INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('playa-juanillo', 'playa-juanillo', 'Playa Juanillo', (SELECT id FROM provinces WHERE slug = 'la-altagracia'), 'salvaleon-de-higuey', 'cap-cana', 'arena-blanca', 'La playa más exclusiva de República Dominicana en el desarrollo de lujo Cap Cana.', 'Playa Juanillo es la joya de Cap Cana, considerada una de las playas más exclusivas del Caribe. Su arena blanca inmaculada y aguas cristalinas crean un escenario perfecto. A diferencia de otras playas de la zona, Juanillo mantiene un ambiente más íntimo y exclusivo, con beach clubs de lujo y restaurantes gourmet.', 'https://images.unsplash.com/photo-1781901227396-34e5fc040091?w=1200&h=800&fit=crop&q=80', 'Playa Juanillo', '[{"url":"https://images.unsplash.com/photo-1781901227396-34e5fc040091?w=1200&h=800&fit=crop&q=80","alt":"Playa Juanillo"},{"url":"https://images.unsplash.com/photo-1781901227396-34e5fc040091?w=1200&h=800&fit=crop&q=80","alt":"Playa Juanillo"},{"url":"https://images.unsplash.com/photo-1781901227396-34e5fc040091?w=1200&h=800&fit=crop&q=80","alt":"Playa Juanillo"}]', '["Snorkel","Kayak","Paddleboard","Paseos en yate","Buceo"]', '["Beach clubs","Restaurantes de lujo","Servicio de playa VIP","Duchas","Estacionamiento"]', 'Turquesa claro', 'Arena blanca muy fina', 'calma', 'baja', 'semi-privado', 1, 1, '10 minutos desde el Aeropuerto de Punta Cana, dentro del desarrollo Cap Cana.', 'Todo el año', 18.4245, -68.3862, 4.9, 1, 1, 'Playa Juanillo | Playas de República Dominicana', 'La playa más exclusiva de República Dominicana en el desarrollo de lujo Cap Cana.', 'published');
INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('playa-macao', 'playa-macao', 'Playa Macao', (SELECT id FROM provinces WHERE slug = 'la-altagracia'), 'salvaleon-de-higuey', NULL, 'virgen', 'Playa salvaje perfecta para surf y escapar de las multitudes.', 'Playa Macao es la alternativa perfecta para quienes buscan una experiencia más auténtica. Esta playa pública, una de las pocas que quedan sin desarrollar en la zona, ofrece olas perfectas para surf y bodyboard. Su arena dorada y palmeras inclinadas crean un escenario tropical clásico.', 'https://images.unsplash.com/photo-1730944527343-74e3e09f088b?w=1200&h=800&fit=crop&q=80', 'Playa Macao', '[{"url":"https://images.unsplash.com/photo-1730944527343-74e3e09f088b?w=1200&h=800&fit=crop&q=80","alt":"Playa Macao"},{"url":"https://images.unsplash.com/photo-1730944527343-74e3e09f088b?w=1200&h=800&fit=crop&q=80","alt":"Playa Macao"},{"url":"https://images.unsplash.com/photo-1730944527343-74e3e09f088b?w=1200&h=800&fit=crop&q=80","alt":"Playa Macao"}]', '["Surf","Bodyboard","Paseos en buggy","Fotografía","Natación"]', '["Restaurantes locales","Vendedores de playa","Estacionamiento"]', 'Azul intenso', 'Arena dorada', 'fuerte', 'media', 'publico', 1, 0, '30 minutos desde Punta Cana hacia el norte.', 'Todo el año, mejor oleaje en invierno', 18.7521, -68.5182, 4.6, 1, 1, 'Playa Macao | Playas de República Dominicana', 'Playa salvaje perfecta para surf y escapar de las multitudes.', 'published');
INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('playa-rincon', 'playa-rincon', 'Playa Rincón', (SELECT id FROM provinces WHERE slug = 'samana'), 'samana', 'las-galeras', 'virgen', 'Considerada una de las mejores playas del mundo por su belleza virgen e intacta.', 'Playa Rincón es consistentemente clasificada entre las mejores playas del mundo. Esta joya de 3 kilómetros de arena dorada rodeada de palmeras y montañas verdes permanece prácticamente intacta. El agua cristalina y la tranquilidad la hacen perfecta para quienes buscan la playa caribeña de sus sueños.', 'https://images.unsplash.com/photo-1541417904950-b855846fe074?w=1200&h=800&fit=crop&q=80', 'Playa Rincón', '[{"url":"https://images.unsplash.com/photo-1541417904950-b855846fe074?w=1200&h=800&fit=crop&q=80","alt":"Playa Rincón"},{"url":"https://images.unsplash.com/photo-1541417904950-b855846fe074?w=1200&h=800&fit=crop&q=80","alt":"Playa Rincón"},{"url":"https://images.unsplash.com/photo-1541417904950-b855846fe074?w=1200&h=800&fit=crop&q=80","alt":"Playa Rincón"},{"url":"https://images.unsplash.com/photo-1541417904950-b855846fe074?w=1200&h=800&fit=crop&q=80","alt":"Playa Rincón"}]', '["Natación","Snorkel","Picnic","Fotografía","Caminatas"]', '["Restaurantes rústicos","Sillas bajo palmeras","Comida local"]', 'Turquesa cristalino', 'Arena dorada fina', 'calma', 'baja', 'publico', 1, 0, 'En bote desde Las Galeras (15 min) o por carretera de tierra (30 min).', 'Diciembre a abril', 19.2638, -69.2505, 5, 1, 1, 'Playa Rincón | Playas de República Dominicana', 'Considerada una de las mejores playas del mundo por su belleza virgen e intacta.', 'published');
INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('playa-coson', 'playa-coson', 'Playa Cosón', (SELECT id FROM provinces WHERE slug = 'samana'), 'las-terrenas', 'las-terrenas', 'virgen', 'Extensa playa salvaje ideal para caminatas románticas al atardecer.', 'Playa Cosón es una de las playas más largas y hermosas de Samaná. Sus 5 kilómetros de arena dorada bordeados de palmeras cocoteras ofrecen un escenario idílico. El oleaje moderado y las corrientes la hacen popular entre surfistas principiantes.', 'https://images.unsplash.com/photo-1730944527343-74e3e09f088b?w=1200&h=800&fit=crop&q=80', 'Playa Cosón', '[{"url":"https://images.unsplash.com/photo-1730944527343-74e3e09f088b?w=1200&h=800&fit=crop&q=80","alt":"Playa Cosón"},{"url":"https://images.unsplash.com/photo-1730944527343-74e3e09f088b?w=1200&h=800&fit=crop&q=80","alt":"Playa Cosón"},{"url":"https://images.unsplash.com/photo-1730944527343-74e3e09f088b?w=1200&h=800&fit=crop&q=80","alt":"Playa Cosón"}]', '["Surf","Caminatas","Cabalgatas","Fotografía"]', '["Restaurantes rústicos","Estacionamiento limitado"]', 'Azul turquesa', 'Arena dorada', 'moderada', 'baja', 'publico', 1, 0, '10 minutos en carro desde Las Terrenas hacia el oeste.', 'Todo el año', 19.342, -69.501, 4.7, 0, 1, 'Playa Cosón | Playas de República Dominicana', 'Extensa playa salvaje ideal para caminatas románticas al atardecer.', 'published');
INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('playa-bonita', 'playa-bonita', 'Playa Bonita', (SELECT id FROM provinces WHERE slug = 'samana'), 'las-terrenas', 'las-terrenas', 'bahia', 'Bahía protegida con aguas tranquilas ideal para familias.', 'Playa Bonita hace honor a su nombre. Esta bahía protegida ofrece aguas tranquilas y poco profundas, perfectas para familias con niños. El ambiente es más relajado que Las Terrenas principal, con pequeños hoteles boutique y restaurantes.', 'https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80', 'Playa Bonita', '[{"url":"https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80","alt":"Playa Bonita"},{"url":"https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80","alt":"Playa Bonita"},{"url":"https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80","alt":"Playa Bonita"}]', '["Natación","Snorkel","Kayak","Paddleboard"]', '["Hoteles boutique","Restaurantes","Sillas de playa"]', 'Verde turquesa', 'Arena dorada', 'calma', 'media', 'publico', 1, 0, '5 minutos desde el centro de Las Terrenas.', 'Todo el año', 19.325, -69.558, 4.6, 0, 0, 'Playa Bonita | Playas de República Dominicana', 'Bahía protegida con aguas tranquilas ideal para familias.', 'published');
INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('playa-sosua', 'playa-sosua', 'Playa Sosúa', (SELECT id FROM provinces WHERE slug = 'puerto-plata'), 'sosua', 'sosua', 'bahia', 'Bahía protegida perfecta para snorkel con vida marina abundante.', 'Playa Sosúa es una pintoresca bahía en forma de herradura protegida por arrecifes de coral. Sus aguas tranquilas y cristalinas albergan una vida marina impresionante, haciéndola uno de los mejores lugares para snorkel en la costa norte. El ambiente es vibrante con restaurantes, bares y vendedores locales.', 'https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80', 'Playa Sosúa', '[{"url":"https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80","alt":"Playa Sosúa"},{"url":"https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80","alt":"Playa Sosúa"},{"url":"https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80","alt":"Playa Sosúa"}]', '["Snorkel","Buceo","Kayak","Paddleboard","Paseos en bote"]', '["Restaurantes","Bares","Alquiler de equipos","Duchas","Baños"]', 'Turquesa claro', 'Arena dorada fina', 'calma', 'alta', 'publico', 1, 1, '20 minutos desde el Aeropuerto de Puerto Plata.', 'Diciembre a abril', 19.7567, -70.5132, 4.6, 1, 1, 'Playa Sosúa | Playas de República Dominicana', 'Bahía protegida perfecta para snorkel con vida marina abundante.', 'published');
INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('playa-cabarete', 'playa-cabarete', 'Playa Cabarete', (SELECT id FROM provinces WHERE slug = 'puerto-plata'), 'sosua', 'cabarete', 'deportiva', 'Capital mundial del kitesurf y windsurf con vientos perfectos todo el año.', 'Playa Cabarete es mundialmente famosa como la capital del kitesurf y windsurf. Los vientos alisios constantes y las condiciones ideales atraen a atletas y entusiastas de todo el mundo. El pueblo tiene un ambiente joven, internacional y vibrante, con excelente vida nocturna.', 'https://images.unsplash.com/photo-1674951447608-8bb6c3e4700d?w=1200&h=800&fit=crop&q=80', 'Playa Cabarete', '[{"url":"https://images.unsplash.com/photo-1674951447608-8bb6c3e4700d?w=1200&h=800&fit=crop&q=80","alt":"Playa Cabarete"},{"url":"https://images.unsplash.com/photo-1674951447608-8bb6c3e4700d?w=1200&h=800&fit=crop&q=80","alt":"Playa Cabarete"},{"url":"https://images.unsplash.com/photo-1674951447608-8bb6c3e4700d?w=1200&h=800&fit=crop&q=80","alt":"Playa Cabarete"},{"url":"https://images.unsplash.com/photo-1674951447608-8bb6c3e4700d?w=1200&h=800&fit=crop&q=80","alt":"Playa Cabarete"}]', '["Kitesurf","Windsurf","Surf","Paddleboard","Yoga en la playa"]', '["Escuelas de kite","Restaurantes","Bares de playa","Alquiler de equipos","Wifi"]', 'Azul atlántico', 'Arena dorada', 'moderada', 'alta', 'publico', 1, 0, '30 minutos desde el Aeropuerto de Puerto Plata.', 'Junio a septiembre para kite, todo el año para surf', 19.7578, -70.4165, 4.7, 1, 1, 'Playa Cabarete | Playas de República Dominicana', 'Capital mundial del kitesurf y windsurf con vientos perfectos todo el año.', 'published');
INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('playa-dorada', 'playa-dorada', 'Playa Dorada', (SELECT id FROM provinces WHERE slug = 'puerto-plata'), 'san-felipe-de-puerto-plata', 'playa-dorada', 'arena-dorada', 'Complejo turístico con playa amplia y resorts todo incluido.', 'Playa Dorada es el principal complejo turístico de Puerto Plata, con una extensa playa de arena dorada bordeada de resorts todo incluido. Ofrece un campo de golf de campeonato, centro comercial y todas las comodidades para unas vacaciones completas.', 'https://images.unsplash.com/photo-1775615752013-85ea1ff73929?w=1200&h=800&fit=crop&q=80', 'Playa Dorada', '[{"url":"https://images.unsplash.com/photo-1775615752013-85ea1ff73929?w=1200&h=800&fit=crop&q=80","alt":"Playa Dorada"},{"url":"https://images.unsplash.com/photo-1775615752013-85ea1ff73929?w=1200&h=800&fit=crop&q=80","alt":"Playa Dorada"},{"url":"https://images.unsplash.com/photo-1775615752013-85ea1ff73929?w=1200&h=800&fit=crop&q=80","alt":"Playa Dorada"}]', '["Golf","Deportes acuáticos","Tenis","Natación"]', '["Resorts all-inclusive","Golf","Centro comercial","Restaurantes","Spa"]', 'Azul atlántico', 'Arena dorada', 'moderada', 'media', 'semi-privado', 1, 1, '10 minutos desde el centro de Puerto Plata.', 'Diciembre a abril', 19.778, -70.632, 4.4, 0, 0, 'Playa Dorada | Playas de República Dominicana', 'Complejo turístico con playa amplia y resorts todo incluido.', 'published');
INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('bahia-de-las-aguilas', 'bahia-de-las-aguilas', 'Bahía de las Águilas', (SELECT id FROM provinces WHERE slug = 'pedernales'), 'pedernales', 'bahia-de-las-aguilas', 'virgen', 'La playa más prístina del Caribe, 8 km de arena virgen sin desarrollo.', 'Bahía de las Águilas es el tesoro más preciado de República Dominicana. Esta playa de 8 kilómetros de arena blanca virgen dentro del Parque Nacional Jaragua es considerada una de las playas más hermosas y prístinas del mundo. Sin desarrollo, sin electricidad, sin ruido - solo naturaleza pura.', 'https://images.unsplash.com/photo-1541417904950-b855846fe074?w=1200&h=800&fit=crop&q=80', 'Bahía de las Águilas', '[{"url":"https://images.unsplash.com/photo-1541417904950-b855846fe074?w=1200&h=800&fit=crop&q=80","alt":"Bahía de las Águilas"},{"url":"https://images.unsplash.com/photo-1541417904950-b855846fe074?w=1200&h=800&fit=crop&q=80","alt":"Bahía de las Águilas"},{"url":"https://images.unsplash.com/photo-1541417904950-b855846fe074?w=1200&h=800&fit=crop&q=80","alt":"Bahía de las Águilas"},{"url":"https://images.unsplash.com/photo-1541417904950-b855846fe074?w=1200&h=800&fit=crop&q=80","alt":"Bahía de las Águilas"}]', '["Natación","Snorkel","Camping","Fotografía","Observación de aves"]', '["Ninguna - llevar todo lo necesario","Botes locales para acceso"]', 'Turquesa cristalino perfecto', 'Arena blanca virgen', 'calma', 'baja', 'publico', 0, 0, 'En bote desde La Cueva o Cabo Rojo (30-45 min). No hay acceso por carretera.', 'Diciembre a abril', 17.8532, -71.6245, 5, 1, 1, 'Bahía de las Águilas | Playas de República Dominicana', 'La playa más prístina del Caribe, 8 km de arena virgen sin desarrollo.', 'published');
INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('playa-boca-chica', 'playa-boca-chica', 'Playa Boca Chica', (SELECT id FROM provinces WHERE slug = 'santo-domingo'), 'boca-chica', 'boca-chica', 'bahia', 'Piscina natural del Caribe, la playa más cercana a Santo Domingo.', 'Boca Chica es famosa por ser una "piscina natural" - una bahía protegida por arrecifes que crea aguas extremadamente tranquilas y poco profundas. Es la escapada de playa favorita de los capitalinos, a solo 30 minutos de Santo Domingo. El ambiente es festivo y familiar los fines de semana.', 'https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80', 'Playa Boca Chica', '[{"url":"https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80","alt":"Playa Boca Chica"},{"url":"https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80","alt":"Playa Boca Chica"},{"url":"https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80","alt":"Playa Boca Chica"}]', '["Natación","Paddleboard","Paseos en bote","Deportes de playa"]', '["Restaurantes","Bares","Sillas y sombrillas","Vendedores locales","Música"]', 'Turquesa claro', 'Arena blanca', 'calma', 'alta', 'publico', 1, 1, '30 minutos desde Santo Domingo por autopista.', 'Todo el año, entre semana para menos gente', 18.4486, -69.6072, 4.3, 1, 1, 'Playa Boca Chica | Playas de República Dominicana', 'Piscina natural del Caribe, la playa más cercana a Santo Domingo.', 'published');
INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('playa-juan-dolio', 'playa-juan-dolio', 'Playa Juan Dolio', (SELECT id FROM provinces WHERE slug = 'san-pedro-de-macoris'), 'guayacanes', 'juan-dolio', 'arena-blanca', 'Playa tranquila con resorts y apartamentos de playa.', 'Juan Dolio ofrece una alternativa más tranquila a Boca Chica. Esta serie de playas conectadas tiene arena suave, aguas claras y un ambiente más relajado. Es popular entre dominicanos de clase media y expatriados que buscan una experiencia de playa accesible.', 'https://images.unsplash.com/photo-1781901227396-34e5fc040091?w=1200&h=800&fit=crop&q=80', 'Playa Juan Dolio', '[{"url":"https://images.unsplash.com/photo-1781901227396-34e5fc040091?w=1200&h=800&fit=crop&q=80","alt":"Playa Juan Dolio"},{"url":"https://images.unsplash.com/photo-1781901227396-34e5fc040091?w=1200&h=800&fit=crop&q=80","alt":"Playa Juan Dolio"},{"url":"https://images.unsplash.com/photo-1781901227396-34e5fc040091?w=1200&h=800&fit=crop&q=80","alt":"Playa Juan Dolio"}]', '["Natación","Snorkel","Golf cercano","Caminatas"]', '["Resorts","Restaurantes","Bares de playa","Estacionamiento"]', 'Azul turquesa', 'Arena blanca', 'calma', 'media', 'publico', 1, 0, '45 minutos desde Santo Domingo por autopista del este.', 'Todo el año', 18.4268, -69.432, 4.2, 0, 0, 'Playa Juan Dolio | Playas de República Dominicana', 'Playa tranquila con resorts y apartamentos de playa.', 'published');
INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('isla-saona', 'isla-saona', 'Isla Saona', (SELECT id FROM provinces WHERE slug = 'la-altagracia'), 'san-rafael-del-yuma', 'bayahibe', 'virgen', 'Isla paradisíaca dentro del Parque Nacional del Este, la excursión más popular de RD.', 'Isla Saona es la excursión de playa más popular de República Dominicana. Esta isla dentro del Parque Nacional del Este ofrece playas vírgenes de postal, piscinas naturales con estrellas de mar, y un ambiente tropical perfecto. Miles de visitantes llegan diariamente en catamaranes desde Bayahíbe.', 'https://images.unsplash.com/photo-1730944527343-74e3e09f088b?w=1200&h=800&fit=crop&q=80', 'Isla Saona', '[{"url":"https://images.unsplash.com/photo-1730944527343-74e3e09f088b?w=1200&h=800&fit=crop&q=80","alt":"Isla Saona"},{"url":"https://images.unsplash.com/photo-1730944527343-74e3e09f088b?w=1200&h=800&fit=crop&q=80","alt":"Isla Saona"},{"url":"https://images.unsplash.com/photo-1730944527343-74e3e09f088b?w=1200&h=800&fit=crop&q=80","alt":"Isla Saona"},{"url":"https://images.unsplash.com/photo-1730944527343-74e3e09f088b?w=1200&h=800&fit=crop&q=80","alt":"Isla Saona"}]', '["Snorkel","Piscinas naturales","Catamarán","Observación de estrellas de mar"]', '["Almuerzo incluido en tours","Barra abierta en tours","Baños"]', 'Turquesa perfecta', 'Arena blanca', 'calma', 'alta', 'publico', 0, 0, 'En catamarán o lancha desde Bayahíbe (45-90 min según embarcación).', 'Diciembre a abril, ir temprano', 18.1508, -68.7189, 4.7, 1, 1, 'Isla Saona | Playas de República Dominicana', 'Isla paradisíaca dentro del Parque Nacional del Este, la excursión más popular de RD.', 'published');
INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('playa-bayahibe', 'playa-bayahibe', 'Playa Bayahíbe', (SELECT id FROM provinces WHERE slug = 'la-altagracia'), 'san-rafael-del-yuma', 'bayahibe', 'bahia', 'Encantador pueblo de pescadores con playa de aguas cristalinas.', 'Bayahíbe es un pintoresco pueblo de pescadores que ha mantenido su encanto a pesar del turismo. Su pequeña playa de aguas cristalinas es perfecta para snorkel y buceo, con acceso a algunos de los mejores sitios de buceo del país.', 'https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80', 'Playa Bayahíbe', '[{"url":"https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80","alt":"Playa Bayahíbe"},{"url":"https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80","alt":"Playa Bayahíbe"},{"url":"https://images.unsplash.com/photo-1781961486948-dd199476488e?w=1200&h=800&fit=crop&q=80","alt":"Playa Bayahíbe"}]', '["Buceo","Snorkel","Kayak","Pesca","Tours a islas"]', '["Restaurantes de pescado","Centros de buceo","Tiendas locales"]', 'Turquesa cristalino', 'Arena blanca', 'calma', 'media', 'publico', 1, 0, '30 minutos desde La Romana, 1.5 horas desde Punta Cana.', 'Todo el año', 18.3622, -68.8438, 4.5, 1, 1, 'Playa Bayahíbe | Playas de República Dominicana', 'Encantador pueblo de pescadores con playa de aguas cristalinas.', 'published');
INSERT OR IGNORE INTO beaches (id, slug, name, province_id, municipality_id, destination_id, beach_type, short_description, description, image_url, image_alt, gallery, activities, amenities, water_color, sand_type, wave_intensity, crowd_level, access_type, parking_available, lifeguard_on_duty, how_to_get_there, best_time_to_visit, latitude, longitude, rating, is_popular, is_featured, seo_title, seo_description, status) VALUES ('playa-san-rafael', 'playa-san-rafael', 'Playa San Rafael', (SELECT id FROM provinces WHERE slug = 'barahona'), 'paraiso', NULL, 'virgen', 'Playa única donde un río de agua dulce y fría se une con el mar.', 'Playa San Rafael es una de las playas más únicas del Caribe. Aquí, un río de agua dulce cristalina y fría fluye directamente hacia el mar Caribe, creando piscinas naturales de agua dulce junto a la playa. El contraste de temperaturas y colores es espectacular.', 'https://images.unsplash.com/photo-1541417904950-b855846fe074?w=1200&h=800&fit=crop&q=80', 'Playa San Rafael', '[{"url":"https://images.unsplash.com/photo-1541417904950-b855846fe074?w=1200&h=800&fit=crop&q=80","alt":"Playa San Rafael"},{"url":"https://images.unsplash.com/photo-1541417904950-b855846fe074?w=1200&h=800&fit=crop&q=80","alt":"Playa San Rafael"},{"url":"https://images.unsplash.com/photo-1541417904950-b855846fe074?w=1200&h=800&fit=crop&q=80","alt":"Playa San Rafael"}]', '["Natación en río","Natación en mar","Fotografía","Picnic"]', '["Comedores locales","Estacionamiento","Baños rústicos"]', 'Azul profundo (mar) / Cristalino (río)', 'Piedras y arena', 'moderada', 'media', 'publico', 1, 0, '40 minutos desde Barahona por la carretera costera.', 'Todo el año', 18.0875, -71.0682, 4.8, 1, 1, 'Playa San Rafael | Playas de República Dominicana', 'Playa única donde un río de agua dulce y fría se une con el mar.', 'published');
